parts.text:
{
  "conversations": [
    {
      "title": "Accept or decline a dance",
      "lines": [
        { "speaker": "partner", "text": "Wanna dance?" },
        { "speaker": "you", "text": "I'd love to." },
        { "speaker": "you", "text": "I'm taking a break right now.", "or": true },
        { "speaker": "partner", "text": "No worries." }
      ]
    },
    {
      "title": "Compliment someone's dancing",
      "lines": [
        { "speaker": "you", "text": "You're a great dancer." },
        { "speaker": "partner", "text": "Thanks so much." },
        { "speaker": "you", "text": "I'm still learning." },
        { "speaker": "partner", "text": "You're doing great." },
        { "speaker": "you", "text": "I appreciate it." }
      ]
    },
    {
      "title": "Chat between songs",
      "lines": [
        { "speaker": "partner", "text": "Come here often?" },
        { "speaker": "you", "text": "This is my first time here." },
        { "speaker": "partner", "text": "How do you like it?" },
        { "speaker": "you", "text": "It's a lot of fun." },
        { "speaker": "partner", "text": "Enjoy the next song." }
      ]
    }
  ]
}
